1	#!/usr/bin/env node
2	import { Command } from 'commander';
3	import * as path from 'path';
4	import { startDevServer } from './devServer';
5	import { buildSite } from './generator';
6	
7	export function run(argv: string[]): void {
8	  const program = new Command();
9	
10	  program.name('ssg').description('A static site generator').version('1.0.0');
11	
12	  program
13	    .command('build')
14	    .description('Generate the site from Markdown content')
15	    .option('--content <dir>', 'content directory', './content')
16	    .option('--output <dir>', 'output directory', './dist')
17	    .option('--templates <dir>', 'templates directory', './templates')
18	    .action((opts: { content: string; output: string; templates: string }) => {
19	      const contentDir = path.resolve(process.cwd(), opts.content);
20	      const outputDir = path.resolve(process.cwd(), opts.output);
21	      const templatesDir = path.resolve(process.cwd(), opts.templates);
22	      const result = buildSite({ contentDir, outputDir, templatesDir });
23	      // eslint-disable-next-line no-console
24	      console.log(`Built ${result.pages.length} page(s) into ${result.outputDir}`);
25	    });
26	
27	  program
28	    .command('serve')
29	    .description('Build the site and serve it with live reload')
30	    .option('--content <dir>', 'content directory', './content')
31	    .option('--output <dir>', 'output directory', './dist')
32	    .option('--templates <dir>', 'templates directory', './templates')
33	    .option('--port <port>', 'port to serve on', '3000')
34	    .action(async (opts: { content: string; output: string; templates: string; port: string }) => {
35	      const contentDir = path.resolve(process.cwd(), opts.content);
36	      const outputDir = path.resolve(process.cwd(), opts.output);
37	      const templatesDir = path.resolve(process.cwd(), opts.templates);
38	      const port = parseInt(opts.port, 10);
39	      const server = await startDevServer({ contentDir, outputDir, templatesDir, port });
40	      // eslint-disable-next-line no-console
41	      console.log(`Serving ${outputDir} at http://localhost:${server.port} (watching ${opts.content}, ${opts.templates})`);
42	    });
43	
44	  program.parse(argv);
45	}
46	
47	if (require.main === module) {
48	  run(process.argv);
49	}
