import { BuildOptions, Page } from './types';

/**
 * Shared state threaded through a build's plugin pipeline. `pages` starts
 * empty and is populated during `beforeBuild` (typically by a
 * content-loading plugin such as MarkdownPlugin) before any `onFile` hook
 * runs.
 */
export interface PluginContext {
  readonly options: BuildOptions;
  pages: Page[];
}

/**
 * A build-lifecycle extension. Every hook is optional; a plugin implements
 * only the stages it cares about. Hooks run in plugin-list order within
 * each stage (see SSGEngine), so a plugin that transforms page content in
 * `onFile` must be listed before a plugin that persists it (e.g.
 * TemplatePlugin) for the transform to take effect.
 */
export interface Plugin {
  name: string;
  onStart?(ctx: PluginContext): void | Promise<void>;
  beforeBuild?(ctx: PluginContext): void | Promise<void>;
  onFile?(page: Page, ctx: PluginContext): Page | void | Promise<Page | void>;
  afterBuild?(ctx: PluginContext): void | Promise<void>;
  onEnd?(ctx: PluginContext): void | Promise<void>;
}

import * as fs from 'fs';
import * as path from 'path';
import { parseMarkdown } from './parser';
import { Page } from './types';

const MARKDOWN_EXTENSIONS = new Set(['.md', '.markdown']);

/**
 * Recursively finds markdown files under `dir`, returning paths relative to
 * `dir` (using forward slashes).
 */
export function findMarkdownFiles(dir: string): string[] {
  const results: string[] = [];

  function walk(current: string) {
    const entries = fs.readdirSync(current, { withFileTypes: true });
    for (const entry of entries) {
      const fullPath = path.join(current, entry.name);
      if (entry.isDirectory()) {
        walk(fullPath);
      } else if (MARKDOWN_EXTENSIONS.has(path.extname(entry.name).toLowerCase())) {
        results.push(path.relative(dir, fullPath).split(path.sep).join('/'));
      }
    }
  }

  if (fs.existsSync(dir)) {
    walk(dir);
  }

  return results;
}

export function loadPages(contentDir: string): Page[] {
  const files = findMarkdownFiles(contentDir);
  return files.map((relativePath) => {
    const raw = fs.readFileSync(path.join(contentDir, relativePath), 'utf-8');
    return parseMarkdown(raw, relativePath);
  });
}

import { Plugin, PluginContext } from './plugin';
import { BuildOptions, BuildResult, Page } from './types';

type StageHook = 'onStart' | 'beforeBuild' | 'afterBuild' | 'onEnd';

function isThenable(value: unknown): value is Promise<unknown> {
  return !!value && typeof (value as { then?: unknown }).then === 'function';
}

/**
 * Orchestrates a build across a list of Plugins. For each stage, every
 * plugin's hook for that stage runs in list order before the next stage
 * begins; `onFile` runs the full plugin chain once per page (in list
 * order) so a plugin can transform a page before a later plugin persists
 * it.
 *
 * `runSync` powers `buildSite()` and requires every hook to complete
 * synchronously (it throws if a plugin returns a Promise); use `run` for
 * pipelines that include async plugins (e.g. DevServerPlugin).
 */
export class SSGEngine {
  constructor(private readonly plugins: Plugin[]) {}

  runSync(options: BuildOptions): BuildResult {
    const ctx: PluginContext = { options, pages: [] };

    this.runStageSync('onStart', ctx);
    this.runStageSync('beforeBuild', ctx);
    ctx.pages = ctx.pages.map((page) => this.runFileHooksSync(page, ctx));
    this.runStageSync('afterBuild', ctx);
    this.runStageSync('onEnd', ctx);

    return { pages: ctx.pages, outputDir: options.outputDir };
  }

  async run(options: BuildOptions): Promise<BuildResult> {
    const ctx: PluginContext = { options, pages: [] };

    await this.runStage('onStart', ctx);
    await this.runStage('beforeBuild', ctx);

    const pages: Page[] = [];
    for (const page of ctx.pages) {
      pages.push(await this.runFileHooks(page, ctx));
    }
    ctx.pages = pages;

    await this.runStage('afterBuild', ctx);
    await this.runStage('onEnd', ctx);

    return { pages: ctx.pages, outputDir: options.outputDir };
  }

  private runStageSync(hook: StageHook, ctx: PluginContext): void {
    for (const plugin of this.plugins) {
      const result = plugin[hook]?.(ctx);
      if (isThenable(result)) {
        throw new Error(
          `Plugin "${plugin.name}" returned a Promise from ${hook}(); use SSGEngine.run() for async plugin pipelines.`
        );
      }
    }
  }

  private runFileHooksSync(page: Page, ctx: PluginContext): Page {
    let current = page;
    for (const plugin of this.plugins) {
      const result = plugin.onFile?.(current, ctx);
      if (isThenable(result)) {
        throw new Error(
          `Plugin "${plugin.name}" returned a Promise from onFile(); use SSGEngine.run() for async plugin pipelines.`
        );
      }
      if (result) current = result;
    }
    return current;
  }

  private async runStage(hook: StageHook, ctx: PluginContext): Promise<void> {
    for (const plugin of this.plugins) {
      await plugin[hook]?.(ctx);
    }
  }

  private async runFileHooks(page: Page, ctx: PluginContext): Promise<Page> {
    let current = page;
    for (const plugin of this.plugins) {
      const result = await plugin.onFile?.(current, ctx);
      if (result) current = result;
    }
    return current;
  }
}

import * as fs from 'fs';
import { loadPages } from '../markdownLoader';
import { Plugin, PluginContext } from '../plugin';

/**
 * Built-in plugin that loads and parses the site's Markdown content.
 * Populates `ctx.pages` during `beforeBuild`, before any `onFile` hook
 * runs.
 */
export function createMarkdownPlugin(): Plugin {
  return {
    name: 'markdown',
    beforeBuild(ctx: PluginContext) {
      const { contentDir } = ctx.options;
      if (!fs.existsSync(contentDir)) {
        throw new Error(`Content directory not found: ${contentDir}`);
      }
      ctx.pages.push(...loadPages(contentDir));
    },
  };
}

import * as fs from 'fs';
import * as path from 'path';
import { TemplateEngine } from '../templateEngine';
import { renderIndex, renderPage } from '../templates';
import { Plugin, PluginContext } from '../plugin';
import { Page } from '../types';

const DEFAULT_STYLESHEET = `body { font-family: sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.6; }
header { margin-bottom: 2rem; }
.page-list { list-style: none; padding: 0; }
.page-list li { margin-bottom: 0.5rem; }
.tags { list-style: none; padding: 0; display: flex; gap: 0.5rem; }
.tags li { background: #eee; border-radius: 0.25rem; padding: 0.1rem 0.5rem; font-size: 0.85rem; }
`;

function writeFile(filePath: string, contents: string): void {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, contents, 'utf-8');
}

/**
 * Built-in plugin that renders each page to HTML (via a Handlebars
 * TemplateEngine when `templatesDir` is set, falling back to the built-in
 * renderer otherwise) and writes it, plus the site index and default
 * stylesheet, to `outputDir`.
 */
export function createTemplatePlugin(): Plugin {
  let engine: TemplateEngine | undefined;

  return {
    name: 'template',
    beforeBuild(ctx: PluginContext) {
      const { outputDir, templatesDir } = ctx.options;
      fs.mkdirSync(outputDir, { recursive: true });
      engine = templatesDir && fs.existsSync(templatesDir) ? new TemplateEngine(templatesDir) : undefined;
    },
    onFile(page: Page, ctx: PluginContext) {
      const html = engine?.renderPage(page, ctx.pages) ?? renderPage(page);
      writeFile(path.join(ctx.options.outputDir, page.outputFile), html);
    },
    afterBuild(ctx: PluginContext) {
      const indexHtml = engine?.renderIndex(ctx.pages) ?? renderIndex(ctx.pages);
      writeFile(path.join(ctx.options.outputDir, 'index.html'), indexHtml);
      writeFile(path.join(ctx.options.outputDir, 'style.css'), DEFAULT_STYLESHEET);
    },
  };
}

import { DevServer, DevServerOptions, startDevServer } from '../devServer';
import { Plugin, PluginContext } from '../plugin';

export interface DevServerPluginOptions {
  /** Port to listen on. Defaults to 3000. Pass 0 to let the OS assign a free port. */
  port?: number;
  /** Called once the server is listening, e.g. to log its port or keep a handle for later shutdown. */
  onServerStart?(server: DevServer): void;
}

/**
 * Built-in plugin that starts the live-reload dev server once a build
 * completes. Only meaningful with `SSGEngine.run()` (the async pipeline),
 * since `startDevServer` itself is async.
 */
export function createDevServerPlugin(options: DevServerPluginOptions = {}): Plugin {
  return {
    name: 'dev-server',
    async onEnd(ctx: PluginContext) {
      const devServerOptions: DevServerOptions = { ...ctx.options, port: options.port };
      const server = await startDevServer(devServerOptions);
      options.onServerStart?.(server);
    },
  };
}

import * as fs from 'fs';
import * as ts from 'typescript';
import { Plugin } from './plugin';

export interface SSGConfig {
  plugins: Plugin[];
  contentDir?: string;
  outputDir?: string;
  templatesDir?: string;
}

let tsRequireHookRegistered = false;

/**
 * Registers a `require.extensions['.ts']` handler that transpiles
 * TypeScript to CommonJS on the fly via the TypeScript compiler API, so
 * plain `require()` can load `ssg.config.ts` (and any `.ts` plugin modules
 * it imports) without a build step. Under Jest, ts-jest already transforms
 * `.ts` requires before Node's `require.extensions` is consulted, so this
 * hook is inert there.
 */
function registerTsRequireHook(): void {
  if (tsRequireHookRegistered || require.extensions['.ts']) {
    tsRequireHookRegistered = true;
    return;
  }
  tsRequireHookRegistered = true;

  require.extensions['.ts'] = (mod: NodeJS.Module, filename: string) => {
    const source = fs.readFileSync(filename, 'utf-8');
    const { outputText } = ts.transpileModule(source, {
      compilerOptions: {
        module: ts.ModuleKind.CommonJS,
        target: ts.ScriptTarget.ES2020,
        esModuleInterop: true,
      },
      fileName: filename,
    });
    (mod as unknown as { _compile(code: string, filename: string): void })._compile(outputText, filename);
  };
}

/**
 * Loads plugin configuration from `configPath` (an `ssg.config.ts` or
 * `.js` module exporting an `SSGConfig`, either as `export default` or
 * CommonJS `module.exports`). Returns `{ plugins: [] }` when the file
 * doesn't exist, so callers can fall back to a default plugin set.
 */
export function loadConfig(configPath: string): SSGConfig {
  if (!fs.existsSync(configPath)) {
    return { plugins: [] };
  }

  registerTsRequireHook();
  delete require.cache[require.resolve(configPath)];
  const loaded = require(configPath);
  const config = (loaded?.default ?? loaded) as Partial<SSGConfig>;

  return {
    plugins: Array.isArray(config.plugins) ? config.plugins : [],
    contentDir: config.contentDir,
    outputDir: config.outputDir,
    templatesDir: config.templatesDir,
  };
}

import { SSGEngine } from './engine';
import { createMarkdownPlugin } from './plugins/markdownPlugin';
import { createTemplatePlugin } from './plugins/templatePlugin';
import { BuildOptions, BuildResult } from './types';

export { findMarkdownFiles, loadPages } from './markdownLoader';

/**
 * Builds the site using the built-in Markdown + Template plugins, run
 * synchronously through SSGEngine. For a custom plugin pipeline (including
 * async plugins like DevServerPlugin), construct an `SSGEngine` directly
 * and call `run()`.
 */
export function buildSite(options: BuildOptions): BuildResult {
  const engine = new SSGEngine([createMarkdownPlugin(), createTemplatePlugin()]);
  return engine.runSync(options);
}

export { buildSite, loadPages, findMarkdownFiles } from './generator';
export { parseMarkdown } from './parser';
export { renderPage, renderIndex, renderArticleBody, renderIndexBody } from './templates';
export { TemplateEngine } from './templateEngine';
export { startDevServer, injectLiveReload } from './devServer';
export { Plugin, PluginContext } from './plugin';
export { SSGEngine } from './engine';
export { loadConfig, SSGConfig } from './config';
export { createMarkdownPlugin } from './plugins/markdownPlugin';
export { createTemplatePlugin } from './plugins/templatePlugin';
export { createDevServerPlugin, DevServerPluginOptions } from './plugins/devServerPlugin';
export * from './types';

